import { precacheAndRoute } from 'workbox-precaching';

// FORMCLUB Service Worker - Real Web Push & Cache Support
const SW_VERSION = 'formclub-sw-v2026-10-15';

// Precache entries generated by Workbox
try {
  precacheAndRoute(self.__WB_MANIFEST || []);
} catch (e) {
  // If manifest not injected in dev
}

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

// Recebimento de Push em Background / Tela Bloqueada
self.addEventListener('push', (event) => {
  let data = {
    title: 'Bem-Estar',
    body: 'Lembre-se de registrar seu bem-estar',
    icon: './pwa/icon-192x192.png',
    badge: './pwa/icon-144x144.png',
    url: '#/monitoring/wellness',
    tag: 'formclub-wellness-reminder'
  };

  if (event.data) {
    try {
      const parsed = event.data.json();
      data = { ...data, ...parsed };
    } catch (e) {
      data.body = event.data.text() || data.body;
    }
  }

  const options = {
    body: data.body,
    icon: data.icon || './pwa/icon-192x192.png',
    badge: data.badge || './pwa/icon-144x144.png',
    tag: data.tag || 'formclub-wellness-reminder',
    renotify: true,
    requireInteraction: false,
    vibrate: [200, 100, 200],
    data: { url: data.url || '#/monitoring/wellness' }
  };

  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

// Ao tocar na notificação na Central de Notificações, abre direto a tela correspondente
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = event.notification.data?.url || '#/monitoring/wellness';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) {
          if (client.url && !client.url.includes(targetUrl.replace('#', ''))) {
            client.navigate(targetUrl);
          }
          return client.focus();
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl);
      }
    })
  );
});
